/* ==========================================================================
   CREATIVE 1-DAY LEFT COUNTDOWN TIMER ENGINE & PROTOCOL GATE
   ========================================================================== */
function initOneDayCountdown() {
  const heroClock = document.getElementById('heroLiveClock');
  const navClock = document.getElementById('navLiveClock');
  const gateClock = document.getElementById('gateCountdownClock');
  const btnBypass = document.getElementById('btnBypassTimer');
  const btnNotify = document.getElementById('btnNotifyMe');
  const notifyInput = document.getElementById('notifyStudentInput');

  function updateClock() {
    const now = new Date();
    const tomorrowMidnight = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 23, 59, 59);
    let diff = Math.max(0, Math.floor((tomorrowMidnight - now) / 1000));

    const hours = Math.floor(diff / 3600);
    diff %= 3600;
    const minutes = Math.floor(diff / 60);
    const seconds = diff % 60;

    const pad = (n) => String(n).padStart(2, '0');
    const timeString = `${pad(hours)}h ${pad(minutes)}m ${pad(seconds)}s`;
    const navString = `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;

    if (heroClock) heroClock.textContent = timeString;
    if (navClock) navClock.textContent = navString;
    if (gateClock) gateClock.textContent = timeString;
  }

  updateClock();
  setInterval(updateClock, 1000);

  // Executive Bypass
  if (btnBypass) {
    btnBypass.addEventListener('click', () => {
      playTone(660, 'sine', 0.1);
      switchStage('stageLanding');
      showToast('🔓 Executive Preview Protocol Unlocked', 'success');
    });
  }

  // Candidate Notify Me
  if (btnNotify && notifyInput) {
    btnNotify.addEventListener('click', () => {
      const val = notifyInput.value.trim();
      if (!val) {
        showToast('Please enter your Student ID or Email address', 'error');
        return;
      }
      playTone(880, 'triangle', 0.12);
      notifyInput.value = '';
      showToast('✓ Notification Registered! We will alert you the moment the portal opens.', 'success');
    });
  }
}

/* ==========================================================================
   STAGE NAVIGATION CONTROLLER
   ========================================================================== */
function switchStage(targetStageId) {
  const allStages = document.querySelectorAll('.app-stage-view');
  allStages.forEach(stage => {
    stage.classList.remove('active-stage');
  });

  const targetStage = document.getElementById(targetStageId);
  if (targetStage) {
    targetStage.classList.add('active-stage');
    window.scrollTo({ top: 0, behavior: 'smooth' });
    playTone(550, 'sine', 0.08);
  }
}

/* ==========================================================================
   DYNAMIC BUSINESS-TECH CONSTELLATION CANVAS ENGINE
   ========================================================================== */
function initConstellationCanvas() {
  const canvas = document.getElementById('constellationCanvas');
  const cursorGlow = document.getElementById('cursorGlow');
  if (!canvas) return;

  const isTouchDevice = ('ontouchstart' in window) || (navigator.maxTouchPoints > 0);
  const isMobile = window.innerWidth < 768;

  const ctx = canvas.getContext('2d', { alpha: true, desynchronized: true });

  const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.25 : 2);
  let width = (canvas.width = window.innerWidth * dpr);
  let height = (canvas.height = window.innerHeight * dpr);
  canvas.style.width = `${window.innerWidth}px`;
  canvas.style.height = `${window.innerHeight}px`;

  let mouse = {
    x: (window.innerWidth / 2) * dpr,
    y: (window.innerHeight / 2) * dpr,
    radius: (isMobile ? 120 : 180) * dpr
  };

  let resizeTimeout = null;
  window.addEventListener('resize', () => {
    if (resizeTimeout) clearTimeout(resizeTimeout);
    resizeTimeout = setTimeout(() => {
      width = canvas.width = window.innerWidth * dpr;
      height = canvas.height = window.innerHeight * dpr;
      canvas.style.width = `${window.innerWidth}px`;
      canvas.style.height = `${window.innerHeight}px`;
      initParticles();
    }, 150);
  }, { passive: true });

  if (!isTouchDevice) {
    window.addEventListener('mousemove', (e) => {
      mouse.x = e.clientX * dpr;
      mouse.y = e.clientY * dpr;
      if (cursorGlow) {
        cursorGlow.style.transform = `translate3d(${e.clientX}px, ${e.clientY}px, 0) translate(-50%, -50%)`;
      }
    }, { passive: true });
  } else if (cursorGlow) {
    cursorGlow.style.display = 'none';
  }

  let particles = [];
  const particleCount = isMobile ? 16 : Math.min(Math.floor(window.innerWidth / 28), 36);
  const maxLineDist = (isMobile ? 85 : 120) * dpr;
  const maxLineDistSq = maxLineDist * maxLineDist;

  class Node {
    constructor() {
      this.reset();
    }
    reset() {
      this.x = Math.random() * width;
      this.y = Math.random() * height;
      this.vx = (Math.random() - 0.5) * (0.35 * dpr);
      this.vy = (Math.random() - 0.5) * (0.35 * dpr);
      this.radius = (1.2 + Math.random() * 1.5) * dpr;
      this.baseAlpha = 0.35 + Math.random() * 0.4;
      this.color = Math.random() > 0.4 ? '#38BDF8' : '#818CF8';
    }
    update() {
      this.x += this.vx;
      this.y += this.vy;

      if (this.x < 0 || this.x > width) this.vx *= -1;
      if (this.y < 0 || this.y > height) this.vy *= -1;

      if (!isTouchDevice && mouse.x > 0) {
        const dx = mouse.x - this.x;
        const dy = mouse.y - this.y;
        const distSq = dx * dx + dy * dy;
        if (distSq < mouse.radius * mouse.radius) {
          const dist = Math.sqrt(distSq);
          const force = (mouse.radius - dist) / mouse.radius;
          this.x -= (dx / dist) * force * 1.2 * dpr;
          this.y -= (dy / dist) * force * 1.2 * dpr;
        }
      }
    }
    draw() {
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
      ctx.fillStyle = this.color;
      ctx.globalAlpha = this.baseAlpha;
      ctx.fill();
    }
  }

  function initParticles() {
    particles = [];
    for (let i = 0; i < particleCount; i++) {
      particles.push(new Node());
    }
  }

  initParticles();

  let isRendering = true;
  document.addEventListener('visibilitychange', () => {
    isRendering = !document.hidden;
    if (isRendering) requestAnimationFrame(renderConstellations);
  });

  function renderConstellations() {
    if (!isRendering) return;

    // Render if stageLanding or stageLaunchTimer is active
    const landingStage = document.getElementById('stageLanding');
    const timerStage = document.getElementById('stageLaunchTimer');
    const isVisibleStage = (landingStage && landingStage.classList.contains('active-stage')) ||
                           (timerStage && timerStage.classList.contains('active-stage'));
    if (!isVisibleStage) {
      requestAnimationFrame(renderConstellations);
      return;
    }

    ctx.clearRect(0, 0, width, height);

    const len = particles.length;

    // BATCHED SINGLE-STROKE PATH DRAWING (Up to 50x faster GPU draw call)
    ctx.beginPath();
    ctx.strokeStyle = '#38BDF8';
    ctx.lineWidth = 0.8 * dpr;
    ctx.globalAlpha = isMobile ? 0.16 : 0.22;

    for (let i = 0; i < len; i++) {
      for (let j = i + 1; j < len; j++) {
        const dx = particles[i].x - particles[j].x;
        const dy = particles[i].y - particles[j].y;
        const distSq = dx * dx + dy * dy;

        if (distSq < maxLineDistSq) {
          ctx.moveTo(particles[i].x, particles[i].y);
          ctx.lineTo(particles[j].x, particles[j].y);
        }
      }
    }
    ctx.stroke();

    // Render node circles
    for (let i = 0; i < len; i++) {
      particles[i].update();
      particles[i].draw();
    }

    requestAnimationFrame(renderConstellations);
  }

  requestAnimationFrame(renderConstellations);
}

/* ==========================================================================
   MAGNETIC BUTTON PULL EFFECT
   ========================================================================== */
function initMagneticButton() {
  const btns = document.querySelectorAll('.btn-primary');
  btns.forEach(btn => {
    btn.addEventListener('mousemove', (e) => {
      const rect = btn.getBoundingClientRect();
      const x = e.clientX - rect.left - rect.width / 2;
      const y = e.clientY - rect.top - rect.height / 2;
      btn.style.transform = `translate(${x * 0.18}px, ${y * 0.18}px) scale(1.04)`;
    });

    btn.addEventListener('mouseleave', () => {
      btn.style.transform = '';
    });
  });
}

