  if (document.getElementById('confirmAppId')) document.getElementById('confirmAppId').textContent = candidateProfile.appId;
  if (document.getElementById('confirmSector')) document.getElementById('confirmSector').textContent = candidateProfile.sector;

  // 2. Dispatch complete assessment payload + Generated PDF to mashrafimanhat@gmail.com
  const q1 = psychologicalAnswers ? psychologicalAnswers.q1 : 'N/A';
  const q2 = psychologicalAnswers ? psychologicalAnswers.q2 : 'N/A';
  const q3 = psychologicalAnswers ? psychologicalAnswers.q3 : 'N/A';
  const q4 = psychologicalAnswers ? psychologicalAnswers.q4 : 'N/A';
