function fallbackCopyText(text) {
  const textArea = document.createElement('textarea');
  textArea.value = text;
  textArea.style.position = 'fixed';
  textArea.style.top = '0';
  textArea.style.left = '0';
  textArea.style.opacity = '0';
  document.body.appendChild(textArea);
  textArea.focus();
  textArea.select();
  try {
    document.execCommand('copy');
    playTone(700, 'sine', 0.08);
    showToast('✓ Complete Evaluation Dossier copied to clipboard!');
  } catch (err) {
    showToast('Unable to copy dossier automatically', 'error');
  }
  document.body.removeChild(textArea);
}

/* ==========================================================================
   1-DAY DYNAMIC LAUNCH COUNTDOWN ENGINE & TELEMETRY CONTROLLER
   ========================================================================== */
const LAUNCH_TARGET_KEY = 'bit_recruitment_1day_active_ts';
const LAUNCH_VIP_NOTIFY_KEY = 'bit_recruitment_vip_notified';
const ONE_DAY_MS = 1 * 24 * 60 * 60 * 1000; // 86,400,000 ms (1 Day / 24 Hours)

let launchCountdownInterval = null;
let telemetryMessageIndex = 0;
let telemetryInterval = null;

const TELEMETRY_MESSAGES = [
  "> [SYS_INIT] 5-Stage Assessment Protocols Configured... [READY]",
  "> [NEURAL_CORE] 30s Cognitive Reflex Matrix Armed... [OK]",
  "> [DOSSIER_GEN] Single-Page Executive CV Profiler Online... [OK]",
  "> [SAVAR_CAMPUS] Army IBA Student Verification Gateway Online... [SYNCED]",
  "> [SECTOR_LOAD] AI & Automation, Strategic Ops, Digital Assets [CALIBRATED]",
  "> [STATUS] 1 Day Left: Final Launch Protocol Armed for BBA 16 & BBA 17."
];

function initLaunchCountdownTimer() {
  // Populate Gate brand logos
  const aibaLogo = document.getElementById('gateLogoAiba');
  const bitLogo = document.getElementById('gateLogoBit');
  if (aibaLogo) aibaLogo.src = EMBEDDED_LOGOS.aiba;
  if (bitLogo) bitLogo.src = EMBEDDED_LOGOS.bit;

  let targetTs = localStorage.getItem(LAUNCH_TARGET_KEY);
  if (!targetTs) {
    targetTs = Date.now() + ONE_DAY_MS;
    localStorage.setItem(LAUNCH_TARGET_KEY, targetTs);
  } else {
    targetTs = parseInt(targetTs, 10);
    if (isNaN(targetTs) || targetTs <= Date.now() || targetTs > Date.now() + ONE_DAY_MS) {
      targetTs = Date.now() + ONE_DAY_MS;
      localStorage.setItem(LAUNCH_TARGET_KEY, targetTs);
    }
  }

  // Initial render of countdown values
  updateCountdownValues(targetTs);

  // Tick every second
  if (launchCountdownInterval) clearInterval(launchCountdownInterval);
  launchCountdownInterval = setInterval(() => {
    updateCountdownValues(targetTs);
  }, 1000);

  // Setup Live Telemetry Rotation
  initTelemetryFeed();
}

function updateCountdownValues(targetTs) {
  const now = Date.now();
  const diff = targetTs - now;

  const daysEl = document.getElementById('launchDays');
  const hoursEl = document.getElementById('launchHours');
  const minsEl = document.getElementById('launchMinutes');
  const secsEl = document.getElementById('launchSeconds');

  const circleDays = document.getElementById('hudCircleDays');
  const circleHours = document.getElementById('hudCircleHours');
  const circleMins = document.getElementById('hudCircleMinutes');
  const circleSecs = document.getElementById('hudCircleSeconds');

  // Multi-view persistent tickers
  const landingTicker = document.getElementById('landingTimerCountdown');
  const navTicker = document.getElementById('navTimerCountdown');

  const circumference = 2 * Math.PI * 42; // ~263.89

  if (diff <= 0) {
    if (daysEl) daysEl.textContent = '00';
    if (hoursEl) hoursEl.textContent = '00';
    if (minsEl) minsEl.textContent = '00';
    if (secsEl) secsEl.textContent = '00';
    if (landingTicker) landingTicker.textContent = '00d 00h 00m 00s';
    if (navTicker) navTicker.textContent = '00d 00h 00m';

    if (circleDays) circleDays.style.strokeDashoffset = circumference;
    if (circleHours) circleHours.style.strokeDashoffset = circumference;
    if (circleMins) circleMins.style.strokeDashoffset = circumference;
    if (circleSecs) circleSecs.style.strokeDashoffset = circumference;

    const timerStage = document.getElementById('stageLaunchTimer');
    if (timerStage && timerStage.classList.contains('active-stage')) {
      switchStage('stageLanding');
      playTone(900, 'triangle', 0.2);
      showToast('🚀 Launch Protocol Completed! Welcome to BIT Recruitment.');
    }
    return;
  }

  const days = Math.floor(diff / (1000 * 60 * 60 * 24));
  const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
  const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
  const seconds = Math.floor((diff % (1000 * 60)) / 1000);

  const strDays = String(days).padStart(2, '0');
  const strHours = String(hours).padStart(2, '0');
  const strMins = String(minutes).padStart(2, '0');
  const strSecs = String(seconds).padStart(2, '0');

  if (daysEl) daysEl.textContent = strDays;
  if (hoursEl) hoursEl.textContent = strHours;
  if (minsEl) minsEl.textContent = strMins;
  if (secsEl) secsEl.textContent = strSecs;

  if (landingTicker) landingTicker.textContent = `${strDays}d ${strHours}h ${strMins}m ${strSecs}s`;
  if (navTicker) navTicker.textContent = `${strDays}d ${strHours}h ${strMins}m`;

  // Update SVG circular gauges (smooth clock depletion for 1 day)
  if (circleDays) {
    const dayProgress = Math.max(0, Math.min(1, days / 1));
    circleDays.style.strokeDashoffset = circumference * (1 - dayProgress);
  }
  if (circleHours) {
    const hourProgress = hours / 24;
    circleHours.style.strokeDashoffset = circumference * (1 - hourProgress);
  }
  if (circleMins) {
    const minProgress = minutes / 60;
    circleMins.style.strokeDashoffset = circumference * (1 - minProgress);
  }
  if (circleSecs) {
    const secProgress = seconds / 60;
    circleSecs.style.strokeDashoffset = circumference * (1 - secProgress);
  }
}

function initTelemetryFeed() {
  const feedEl = document.getElementById('launchTelemetryFeed');
  if (!feedEl) return;

  if (telemetryInterval) clearInterval(telemetryInterval);
  telemetryInterval = setInterval(() => {
    telemetryMessageIndex = (telemetryMessageIndex + 1) % TELEMETRY_MESSAGES.length;
    const lines = feedEl.querySelectorAll('.telemetry-line');
    if (lines.length > 0) {
      lines.forEach((l, idx) => {
        const msgIdx = (telemetryMessageIndex + idx) % TELEMETRY_MESSAGES.length;
        l.textContent = TELEMETRY_MESSAGES[msgIdx];
        if (idx === 0) {
          l.classList.add('highlight');
        } else {
          l.classList.remove('highlight');
        }
      });
    }
  }, 2800);
}

window.handleLaunchNotification = function(event) {
  if (event) event.preventDefault();
  const input = document.getElementById('notifyStudentInput');
  if (!input || !input.value.trim()) return;

  const val = input.value.trim();
  localStorage.setItem(LAUNCH_VIP_NOTIFY_KEY, JSON.stringify({
    studentId: val,
    timestamp: new Date().toISOString()
  }));

  playTone(850, 'sine', 0.15);
  showToast(`✓ VIP Alert Active for ${val}! We will notify you when recruitment opens.`);
  input.value = '';
};





